#!/usr/bin/env python3
"""Compile real identity sources/tests using supplied verified JDK/dependency directories.
No networking, credentials, production files or downloaded executable code.
"""
import argparse,hashlib,json,os,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--jdk',required=True,type=Path);p.add_argument('--deps',required=True,action='append',type=Path);p.add_argument('--out',required=True,type=Path);a=p.parse_args()
project=Path(__file__).resolve().parents[2];a.out.mkdir(parents=True,exist_ok=True);classes=a.out/'classes';classes.mkdir(exist_ok=True)
sources=sorted([*(project/'common-protocol/src/main/java/org/securemail/ecosystem/protocol').glob('*.java'),*(project/'identity-server/src/main/java').rglob('*.java'),*(project/'identity-server/src/test/java').rglob('*.java')]);jars=sorted({j.resolve() for dep in a.deps for j in dep.glob('*.jar')});cp=os.pathsep.join(map(str,jars));javac=[str(a.jdk/'bin/javac'),'-encoding','UTF-8','-Xlint:all','-g','-cp',cp,'-d',str(classes),*map(str,sources)];source_hashes={str(f.relative_to(project)):hashlib.sha256(f.read_bytes()).hexdigest() for f in sources};r=subprocess.run(javac,capture_output=True,text=True);(a.out/'javac.log').write_text(r.stdout+r.stderr);print(r.stdout+r.stderr,end='');record={'scope':'local JDK21 SQLite/HTTP fixtures, not Tor/native/production','sources':source_hashes,'compileExit':r.returncode}
if r.returncode: (a.out/'RESULTS.json').write_text(json.dumps(record,indent=2));raise SystemExit(r.returncode)
# Prove the Android-shared codec does not require Java21 source/API.
android=a.out/'shared-java8';android.mkdir(exist_ok=True);shared=[str(f) for f in sources if '/common-protocol/' in str(f)];r8=subprocess.run([str(a.jdk/'bin/javac'),'--release','8','-encoding','UTF-8','-d',str(android),*shared],capture_output=True,text=True);(a.out/'shared-java8.log').write_text(r8.stdout+r8.stderr);record['sharedJava8Exit']=r8.returncode
junit=[str(a.jdk/'bin/java'),'-cp',str(classes)+os.pathsep+cp,'org.junit.platform.console.ConsoleLauncher','execute','--scan-classpath',str(classes),'--disable-ansi-colors','--reports-dir',str(a.out/'junit')];r=subprocess.run(junit,capture_output=True,text=True);(a.out/'junit.log').write_text(r.stdout+r.stderr);print(r.stdout+r.stderr,end='');record['testExit']=r.returncode;record['sourceStable']=source_hashes=={str(f.relative_to(project)):hashlib.sha256(f.read_bytes()).hexdigest() for f in sources};record['status']='PASS_LOCAL' if r.returncode==r8.returncode==0 and record['sourceStable'] else 'SOURCE_CHANGED' if not record['sourceStable'] else 'FAIL';(a.out/'RESULTS.json').write_text(json.dumps(record,indent=2)+'\n');raise SystemExit(r.returncode or r8.returncode or (0 if record["sourceStable"] else 2))
